import os
for r,d,f in os.walk('studies'):
    for x in f: print(os.path.join(r,x), os.path.getsize(os.path.join(r,x)))

import re, gzip, tarfile, io
pat=re.compile(r'(?<![\w.-])(\d{1,2}-(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)|(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)-\d{1,2})(?![\w-])',re.I)
def scan(name,text):
    hits=set(m.group(0) for m in pat.finditer(text))
    print(name, sorted(hits)[:40], len(hits))
scan('GPL10371',open('studies/data/raw/paper_2_GPL10371.txt',errors='ignore').read())
for f in ['paper_1_GSE4025_series_matrix.txt.gz','paper_2_GSE21618_series_matrix.txt.gz','paper_3_GSE26298_series_matrix.txt.gz','paper_4_GSE111151_series_matrix.txt.gz','paper_5_GSE117942_series_matrix.txt.gz','paper_5_GSE117942_RNA-seq_counts.tsv.gz']:
    scan(f,gzip.open('studies/data/raw/'+f,'rt',errors='ignore').read())
t=tarfile.open('studies/data/raw/paper_4_GSE111151_RAW.tar')
for m in t.getmembers():
    txt=gzip.decompress(t.extractfile(m).read()).decode(errors='ignore')
    scan(m.name,txt)
    if m.name.endswith('053_MCF-7.txt.gz'): print(txt[:300])
